const LIGHT = {r:0.93, g:0.93, b:0.95}; // ~#EEEEF2
const ACCENT = {r:0.835, g:0.286, b:0.114}; // #D5491D

async function recolor(id, color, skip) {
  const comp = await figma.getNodeByIdAsync(id);
  const vectors = comp.findAll(n => n.type === 'VECTOR' || n.type === 'BOOLEAN_OPERATION');
  for (const v of vectors) {
    if (skip && skip(v)) continue;
    v.fills = [{type:'SOLID', color}];
  }
  return {name: comp.name, count: vectors.length};
}
const results = [];
for (const id of ['7:8','7:10','7:14','7:16','7:18','7:20','7:22','7:24','7:26','7:4']) {
  results.push(await recolor(id, LIGHT));
}
// JavaScript logo: has a yellow bg square + JS letters; make square accent orange and letters light
const js = await figma.getNodeByIdAsync('7:12');
const jsVecs = js.findAll(n => n.type === 'VECTOR' || n.type === 'BOOLEAN_OPERATION');
const jsInfo = jsVecs.map(v => ({name: v.name, w: v.width, h: v.height}));
for (const v of jsVecs) {
  // background square is the largest
  if (v.width > 30) v.fills = [{type:'SOLID', color: ACCENT}];
  else v.fills = [{type:'SOLID', color: {r:1,g:1,b:1}}];
}
return {results, jsInfo};

