function describe(n, depth) {
  const o = {type:n.type, name:n.name, w:Math.round(n.width), h:Math.round(n.height)};
  if (n.fills) o.fills = JSON.stringify(n.fills).slice(0,200);
  if (depth < 4 && n.children) o.children = n.children.map(c => describe(c, depth+1));
  return o;
}
return describe(abm, 0);

