async function socialComp(name, iconId, scale) {
  const c = figma.createComponent();
  c.name = name;
  c.resize(44,44);
  c.cornerRadius = 22;
  fillVar(c, vars.surface2, '#1C1C24');
  strokeVar(c, vars.border, '#2A2A33');
  c.strokeWeight = 1;
  c.layoutMode = 'HORIZONTAL';
  c.primaryAxisAlignItems = 'CENTER';
  c.counterAxisAlignItems = 'CENTER';
  const i = await inst(iconId);
  i.rescale(scale);
  c.appendChild(i);
  page.appendChild(c);
  return c;
}
