  const targetH = 16 + (t.fontSize * 1.35) + (hasDot ? 11 : 0); // padding 8+8 + text + dot(5+6 gap)
  item.counterAxisSizingMode = 'AUTO';
  item.primaryAxisSizingMode = 'AUTO';
  fixes.push({name: item.name, w: item.width, h: item.height});
}
