function dump(n, d) {
  const o = {type: n.type, name: n.name, w: Math.round(n.width*100)/100, h: Math.round(n.height*100)/100};
  if (n.strokes) o.strokes = JSON.stringify(n.strokes).slice(0,120);
  if (n.strokeWeight !== undefined) o.strokeWeight = n.strokeWeight;
  if (d < 4 && n.children) o.children = n.children.map(c => dump(c, d+1));
  return o;
}
