function stage(name, w, h) {
  const f = figma.createFrame();
  f.name = name;
  f.resize(w, h);
  f.cornerRadius = 16;
  f.fills = [DARK];
  page.appendChild(f);
  f.clipsContent = false;
  return f;
}
function place(f, node, pad) {
  f.appendChild(node);
  node.x = pad; node.y = pad;
  f.resize(node.width + pad*2, node.height + pad*2);
  return f;
}

