// add stage captions inside each stage top area
function caption(stageF, text) {
  const t = figma.createText();
  t.fontName = {family:'Poppins', style:'Medium'};
  t.fontSize = 13;
  t.characters = text;
  t.fills = [{type:'SOLID', color:{r:0.55,g:0.55,b:0.62}}];
  stageF.appendChild(t);
  t.x = pad; t.y = stageF.height + 12;
  return t;
}
caption(media, 'MEDIA — copied from 04 · Media, recolored for the dark page');
caption(btnNav, 'BUTTONS & NAV — default / hover / current variants');
caption(biz, 'SECTIONS & CARDS — header, tech row, project cards, experience, contact');

return {mediaH: media.height, bizH: biz.height, bizW: biz.width};

const page = await figma.getNodeByIdAsync('5:2');
// get bounds of all page content
let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
for (const c of page.children) {
  minX = Math.min(minX, c.x);
  minY = Math.min(minY, c.y);
  maxX = Math.max(maxX, c.x + c.width);
  maxY = Math.max(maxY, c.y + c.height);
}
// create a wrapper to screenshot everything
const wrap = figma.createFrame();
wrap.name = 'tmp_view';
for (const c of [...page.children]) {
  if (c === wrap) continue;
  wrap.appendChild(c);
}
page.appendChild(wrap);
const id = wrap.id;
// move so top-left at 0
const dx = wrap.children.reduce((m, c) => Math.min(m, c.x), Infinity);
const dy = wrap.children.reduce((m, c) => Math.min(m, c.y), Infinity);
for (const c of wrap.children) { c.x -= dx; c.y -= dy; }
wrap.clipsContent = false;
wrap.fills = [];
return {wrapId: id, w: maxX - minX, h: maxY - minY};

const wrap = await figma.getNodeByIdAsync('39:115');
return {
