  childrenX: wrap.children.map(c => ({name: c.name, x: Math.round(c.x), y: Math.round(c.y)})).slice(0, 8),
  minX: Math.min(...wrap.children.map(c => c.x)),
  minY: Math.min(...wrap.children.map(c => c.y)),
  maxX: Math.max(...wrap.children.map(c => c.x + c.width)),
  maxY: Math.max(...wrap.children.map(c => c.y + c.height)),
};

