const page = await figma.getNodeByIdAsync('5:2');
const media = page.children.find(c => c.name === 'Library · Media');
const pad = 32, gap = 28, maxW = 1420;
let mx = pad, my = pad, rowH = 0, widest = 0;
const caption = media.children.find(c => c.type === 'TEXT');
for (const n of media.children) {
  if (n === caption) continue;
  if (mx > pad && mx + n.width > maxW) { mx = pad; my += rowH + gap; rowH = 0; }
  n.x = mx; n.y = my;
  mx += n.width + gap;
  rowH = Math.max(rowH, n.height);
  widest = Math.max(widest, n.x + n.width);
}
media.resize(widest + pad, my + rowH + pad);
caption.x = pad;
caption.y = media.height + 12;
return {mediaW: media.width, mediaH: media.height};

const page = await figma.getNodeByIdAsync('5:2');
const btnNav = page.children.find(c => c.name === 'Library · Buttons & Nav');
const pad = 32, gap = 28;
// vertical stack of the two sets
const sets = btnNav.children.filter(c => c.type === 'COMPONENT_SET');
const caption = btnNav.children.find(c => c.type === 'TEXT');
let by = pad, maxW = 0;
for (const s of sets) {
  s.x = pad; s.y = by;
  by += s.height + gap;
  maxW = Math.max(maxW, s.width);
}
btnNav.resize(maxW + pad*2, by - gap + pad);
caption.x = pad; caption.y = btnNav.height + 12;
return {btnNavW: btnNav.width, btnNavH: btnNav.height, setCount: sets.length};

