ws.appendChild(home);
home.x = 0; home.y = 0;
return {parent: home.parent.name, x: home.x, y: home.y};

const home = await figma.getNodeByIdAsync('16:2');
const headerInst = home.findOne(n => n.name === 'Header');
const nav = headerInst.findOne(n => n.name === 'Nav');
const out = {
  nav: nav.children.map(item => ({label: item.findOne(n => n.type === 'TEXT').characters, reactions: item.reactions.length})),
};
const hero = home.findOne(n => n.name === 'Section / Hero');
const ctaRow = hero.findOne(n => n.name === 'CTA row');
out.getInTouch = ctaRow.children[0].reactions.length;
const cardsRow = home.findOne(n => n.name === 'Section / Projects').findOne(n => n.name === 'Cards row');
out.cards = cardsRow.children.map(c => c.reactions.length);
const footerInst = home.children.find(c => c.name === 'Contact Section');
out.email = footerInst.findOne(n => n.name === 'Email pill').reactions.length;
out.socials = footerInst.findOne(n => n.name === 'Social row').children.map(s => s.reactions.length);
return out;
